local function sld(p,txt,mn,mx,df,cb)local h=Instance.new("Frame")h.Size=UDim2.new(1,0,0,44)h.BackgroundTransparency=1 h.Parent=p local l=Instance.new("TextLabel")l.Text=txt l.Font=Enum.Font.Gotham l.TextSize=11 l.TextColor3=Color3.fromRGB(240,230,220)l.BackgroundTransparency=1 l.Size=UDim2.new(1,-45,0,14)l.TextXAlignment=Enum.TextXAlignment.Left l.Parent=h local v=Instance.new("TextLabel")v.Text=tostring(df)v.Font=Enum.Font.GothamBold v.TextSize=11 v.TextColor3=Color3.fromRGB(255,160,60)v.BackgroundTransparency=1 v.Size=UDim2.new(0,40,0,14)v.Position=UDim2.new(1,-40,0,0)v.TextXAlignment=Enum.TextXAlignment.Right v.Parent=h local bb=Instance.new("Frame")bb.Size=UDim2.new(1,0,0,7)bb.Position=UDim2.new(0,0,0,24)bb.BackgroundColor3=Color3.fromRGB(65,50,40)bb.BorderSizePixel=0 bb.Parent=h Instance.new("UICorner",bb).CornerRadius=UDim.new(1,0)local fl=Instance.new("Frame")fl.Size=UDim2.new((df-mn)/(mx-mn),0,1,0)fl.BackgroundColor3=Color3.fromRGB(255,140,40)fl.BorderSizePixel=0 fl.Parent=bb Instance.new("UICorner",fl).CornerRadius=UDim.new(1,0)local k=Instance.new("Frame")k.Size=UDim2.new(0,14,0,14)k.Position=UDim2.new((df-mn)/(mx-mn),-7,.5,-7)k.BackgroundColor3=Color3.fromRGB(255,255,255)k.Parent=bb Instance.new("UICorner",k).CornerRadius=UDim.new(1,0)local dr=false local function up(x)local r=math.clamp((x-bb.AbsolutePosition.X)/bb.AbsoluteSize.X,0,1)local val=math.floor(mn+(mx-mn)*r+.5)fl.Size=UDim2.new(r,0,1,0)k.Position=UDim2.new(r,-7,.5,-7)v.Text=tostring(val)if cb then cb(val)end end bb.InputBegan:Connect(function(i)if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then dr=true up(i.Position.X)end end)U.InputChanged:Connect(function(i)if dr and (i.UserInputType==Enum.UserInputType.MouseMovement or i.UserInputType==Enum.UserInputType.Touch)then up(i.Position.X)end end)U.InputEnded:Connect(function(i)if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then dr=false end end)end
