task.spawn(function()while St.R do pcall(function()if St.AF then local c=L.Character local h=c and c:FindFirstChild("HumanoidRootPart")if h then for _,o in ipairs(W:GetDescendants())do if o:IsA("Model")and o.Name=="Super Honey"and o.Parent then local prim=o.PrimaryPart or o:FindFirstChildWhichIsA("BasePart",true)if prim then h.CFrame=CFrame.new(prim.Position+Vector3.new(0,3,0))task.wait(0.3)end end end end end end)task.wait(0.3)end end)

-- AUTO COLETAR: LOOP 1 (pequenos + medios)
task.spawn(function()while St.R do pcall(function()if St.AC then local c=L.Character local h=c and c:FindFirstChild("HumanoidRootPart")if h then local meuNome=L.Name:lower()local meuTerreno=nil for _,obj in ipairs(W:GetDescendants())do if obj:IsA("Model")and obj.Parent and obj.Name:lower():find(meuNome)then meuTerreno=obj break end end if meuTerreno then for _,obj in ipairs(meuTerreno:GetDescendants())do if obj:IsA("Model")and obj.Parent then local n=obj.Name:lower()if (n:find("apiary")or n:find("beehive"))and not n:find("large apiary")and not n:find("loja")then local prim=obj.PrimaryPart if not prim then prim=obj:FindFirstChildWhichIsA("BasePart",true)end if prim then local pA=h.CFrame h.CFrame=CFrame.new(prim.Position+Vector3.new(0,3,0))task.wait(0.15)h.CFrame=pA task.wait(0.02)end end end end end end end end)task.wait(0.5)end end)

-- AUTO COLETAR: LOOP 2 (Large apiary + Honey barrel, usando PECA MAIS ALTA)
task.spawn(function()while St.R do pcall(function()if St.AC then local c=L.Character local h=c and c:FindFirstChild("HumanoidRootPart")if h then local meuNome=L.Name:lower()local meuTerreno=nil for _,obj in ipairs(W:GetDescendants())do if obj:IsA("Model")and obj.Parent and obj.Name:lower():find(meuNome)then meuTerreno=obj break end end if meuTerreno then for _,obj in ipairs(meuTerreno:GetDescendants())do if obj:IsA("Model")and obj.Parent then local nb=obj.Name:lower() if nb=="large apiary" or nb=="honey barrel" then local maisAlta=nil local maiorY=-9999 for _,p in ipairs(obj:GetDescendants())do if p:IsA("BasePart")and p.Position.Y>maiorY then maiorY=p.Position.Y maisAlta=p end end if maisAlta then local pA=h.CFrame h.CFrame=CFrame.new(maisAlta.Position+Vector3.new(0,3,0))task.wait(0.3)h.CFrame=pA task.wait(0.1)end end end end end end end end)task.wait(3)end end)

